#!/usr/bin/env node
// One product version, two build systems.
//
// Changesets owns the number: it bumps the workspace packages, which are pinned to each other
// so the phone and the Mac always release together. Neither Gradle nor Xcode can read a
// package.json, so this writes the number into a generated file each of them already includes.
// Run it after `changeset version`; CI runs it before building so a tag can never produce
// artefacts stamped with the previous version.

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const read = (path) => JSON.parse(readFileSync(join(root, path), 'utf8'))

const version = read('android/package.json').version
const macosVersion = read('macos/package.json').version

if (version !== macosVersion) {
  console.error(
    `the two packages disagree: android is ${version}, macos is ${macosVersion}.\n` +
      'They are a fixed group in .changeset/config.json, so this should not happen — ' +
      'check that config before releasing.',
  )
  process.exit(1)
}

const [major, minor, patch] = version.split('.').map(Number)
if ([major, minor, patch].some((part) => !Number.isInteger(part))) {
  console.error(`cannot parse "${version}" as major.minor.patch`)
  process.exit(1)
}

// Android requires a monotonically increasing integer, and refuses an install that would go
// backwards. Two digits per part keeps that true up to x.99.99.
if (minor > 99 || patch > 99) {
  console.error(`minor and patch must stay below 100 to keep versionCode monotonic: ${version}`)
  process.exit(1)
}
const versionCode = major * 10000 + minor * 100 + patch

writeFileSync(
  join(root, 'android/version.properties'),
  `# Generated by scripts/sync-versions.mjs — do not edit.\n` +
    `versionName=${version}\n` +
    `versionCode=${versionCode}\n`,
)

writeFileSync(
  join(root, 'macos/Config/Version.xcconfig'),
  `// Generated by scripts/sync-versions.mjs — do not edit.\n` +
    `MARKETING_VERSION = ${version}\n` +
    `CURRENT_PROJECT_VERSION = ${versionCode}\n`,
)

const rootPackage = read('package.json')
if (rootPackage.version !== version) {
  rootPackage.version = version
  writeFileSync(join(root, 'package.json'), `${JSON.stringify(rootPackage, null, 2)}\n`)
}

console.log(`version ${version} (versionCode ${versionCode}) written to both build systems`)
